if m.loadingTree() { st = Status{Text: "Loading …", Spinner: true} } else if m.refreshing > 0 { st = Status{Text: "Updating from …", Spinner: true} }
if m.mode == ModeNormal { if node, ok := m.selectedNode(); ok { st.Detail = m.rowActivity(node).Detail } }
return st
// delete.go, on error:
