	}
	if c.MinWidth != datatable.IconColumnWidth {
		bad = append(bad, fmt.Sprintf("MinWidth %d (want IconColumnWidth)", c.MinWidth))
	}
	if c.Less || c.Search {
		bad = append(bad, "declares Less or Search")
	}
	if len(bad) > 0 {
