package explorer

import (
	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/jobs"
)

// What this view knows about the work it has started is a snapshot the router
// hands it, and nothing else (D1).
//
// The clone was already registered; the create and the delete were not, and
// they are the two that talk to a forge over the network. Left outside, each
// would have needed its own flag, its own blink chain and its own guard —
// which is the fourth bookkeeping the package doc of internal/jobs opens by
// describing, and the animation is the half that fails silently: this view's
// own spinner chain stops on `!m.loading` (handleSpinnerTick), so a blink
// phase taken from it would freeze the moment the tree settled.

// createRun and deleteRun are single-target runs. The label is the name a human
// gave the thing, not the path: it is what `:jobs` shows, and the path is
// already the target.
func createRun(target, label string) jobs.Run {
	return jobs.NewImmediateRun(jobs.KindCreate, command.ViewGitExplorer, "", label, target)
}

func deleteRun(target, label string) jobs.Run {
	return jobs.NewImmediateRun(jobs.KindDelete, command.ViewGitExplorer, "", label, target)
}

// liveRuns returns the runs still going, whatever view started them.
//
// Filtered to this view's kinds, which is the difference from workspaces: a
// scan running in `ws` names a directory on disk, and the paths in this tree
// are the forge's. Two identically-named strings from two namespaces would
// otherwise spin a row here for work that has nothing to do with it.
func (m Model) liveRuns() []jobs.Run {
	out := make([]jobs.Run, 0, len(m.jobs))
	for _, run := range jobs.Unfinished(m.jobs) {
		if run.Kind == jobs.KindCreate || run.Kind == jobs.KindDelete {
			out = append(out, run)
		}
	}
	return out
}

// workingKind reports whether a path is queued or running under one kind.
func (m Model) workingKind(kind jobs.Kind, target string) bool {
	for _, run := range m.liveRuns() {
		if run.Kind != kind {
			continue
		}
		for _, item := range run.Items {
			if item.Target == target && !item.State.Terminal() {
				return true
			}
		}
	}
	return false
}

// creating and deleting are the two readings the rows and the guards need.
func (m Model) creating(path string) bool { return m.workingKind(jobs.KindCreate, path) }
func (m Model) deleting(path string) bool { return m.workingKind(jobs.KindDelete, path) }

// busyMessage is what an action says when the forge is already being asked
// something about this row. One message rather than two, because the user's
// next move is the same either way: wait.
const busyMessage = "Already busy — a create or delete is running here"

// busy reports whether the row is held by work in flight.
//
// It answers from the registry, so it sees work started anywhere — which for
// this view means a second window on the same tree cannot issue the delete a
// first one is already running.
func (m Model) busy(path string) bool {
	return m.creating(path) || m.deleting(path)
}

// ── What each message tells the registry (jobs.Reporter) ─────────────────────
//
// The mapping lives here rather than in the router for the reason Reporter
// exists: "a project whose template failed still exists" is this package's
// vocabulary, and a router that knew it would grow a branch per view.

func (m GroupCreatedMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindCreate, Target: m.Target, State: jobs.ItemDone}
	if m.Error != nil {
		t.State = jobs.ItemFailed
		t.Detail = "create failed — check logs"
	}
	return t
}

func (m ProjectCreatedMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindCreate, Target: m.Target, State: jobs.ItemDone}
	switch {
	case m.Error != nil && m.TemplateUnavailable:
		// Nothing was created: the template was fetched first, and could not be.
		t.State = jobs.ItemFailed
		t.Detail = "template unavailable — nothing was created"
	case m.Error != nil:
		t.State = jobs.ItemFailed
		t.Detail = "create failed — check logs"
	case m.TemplateError != nil:
		// The project exists, empty, but what was asked for was a repository
		// with a template in it: the run says it did not get there rather than
		// reading as a success. The row still settles (handleProjectCreated).
		t.State = jobs.ItemFailed
		t.Detail = "created empty — the template's commit failed"
	}
	return t
}

func (m DeleteCompleteMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindDelete, Target: m.Target, State: jobs.ItemDone}
	if m.Error != nil {
		t.State = jobs.ItemFailed
		t.Detail = "delete failed — check logs"
	}
	return t
}

// Compile-time proof that every message reporting on registered work can be
// applied to the registry. One added without it would be routed, would update
// the view, and would leave its row spinning for the life of the view — which
// is precisely the failure the registry exists to remove.
var (
	_ jobs.Reporter = GroupCreatedMsg{}
	_ jobs.Reporter = ProjectCreatedMsg{}
	_ jobs.Reporter = DeleteCompleteMsg{}
package explorer

import (
	"context"
	"fmt"
	"log"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/forge"
	"github.com/anthnel/devdesk/internal/forgeindex"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/components"
)

// handleDeleteStart handles ctrl+d key - start delete operation
func (m Model) handleDeleteStart() (tea.Model, tea.Cmd) {
	// Rule 130: the key is greyed for every one of these — no session, no row,
	// a row the forge has not confirmed, a row already busy — and pressing it
	// anyway says which one it is rather than doing nothing. The check comes
	// before the lookup so a missing row is named too.
	if act := m.actionable(); !act.Enabled() {
		return m, m.footer.Warn(act.Reason)
	}
	node, ok := m.selectedNode()
	if !ok {
		return m, nil
	}

	m.deleteTargetNode = node
	m.mode = ModeConfirmingDelete

	// Project already scheduled for deletion: only permanent removal is possible.
	if node.Type == NodeTypeProject && node.MarkedForDeletion {
		title := "Permanently Delete Project"
		message := fmt.Sprintf("'%s' is already scheduled for deletion.\n\nConfirm to permanently delete it now.", node.Name)
		m.deleteConfirmModal = components.NewDeleteConfirmModalLocked(title, message)
		return m, nil
	}

	var title, message string
	if node.Type == NodeTypeGroup {
		title = "Delete Group"
		message = fmt.Sprintf("Are you sure you want to delete the group '%s'?\n\nThis will delete the group and ALL its contents\n(subgroups, projects, issues, etc.).", node.Name)
	} else {
		title = "Delete Project"
		message = fmt.Sprintf("Are you sure you want to delete the project '%s'?\n\nThis will delete the project and all its data\n(code, issues, merge requests, etc.).", node.Name)
	}

	offerImmediate := m.shared.Forge != nil && m.shared.Forge.Shape().PermanentDelete
	m.deleteConfirmModal = components.NewDeleteConfirmModal(title, message, offerImmediate)
	return m, nil
}

// handleDeleteConfirmed handles confirmation of delete
func (m Model) handleDeleteConfirmed(permanentlyRemove bool) (tea.Model, tea.Cmd) {
	m.mode = ModeNormal
	m.deleteConfirmModal = nil

	node := m.deleteTargetNode
	m.deleteTargetNode = nil

	if node == nil {
		return m, nil
	}

	backend := m.shared.Forge
	if backend == nil {
		m.error = "Not connected to a forge"
		return m, nil
	}

	// The whole value goes to the backend, not just an identifier: a permanent
	// deletion addresses the path the forge renames the object to, so the call
	// needs both (see forge.Forge.DeleteNamespace).
	nodeType := node.Type
	id, path := node.ID, node.FullPath

	if m.busy(path) {
		return m, m.footer.Warn(busyMessage)
	}

	work := func() tea.Msg {
		var err error
		if nodeType == NodeTypeGroup {
			err = backend.DeleteNamespace(context.Background(), forge.Namespace{ID: id, Path: path}, permanentlyRemove)
		} else {
			err = backend.DeleteRepository(context.Background(), forge.Repository{ID: id, Path: path}, permanentlyRemove)
		}
		return DeleteCompleteMsg{Error: err, Target: path, DeletedNode: node}
	}
	// The row keeps its place and blinks its dot while the forge works — the
	// same treatment a create gets, and for the same reason: a delete is a
	// network call, and a row that vanished before the answer came would be
	// claiming something that has not happened yet.
	return m, jobs.Start(deleteRun(path, node.Name), work)
}

// removeNode drops node from level, by identity first and by ID as a fallback
// (a refresh may have replaced the pointer since the delete was asked).
func removeNode(level []*TreeNode, node *TreeNode) []*TreeNode {
	for i, n := range level {
		if n == node || (n.ID != "" && n.ID == node.ID) {
			return append(level[:i], level[i+1:]...)
		}
	}
	return level
}

// handleDeleteComplete handles DeleteCompleteMsg
func (m Model) handleDeleteComplete(msg DeleteCompleteMsg) (tea.Model, tea.Cmd) {
	if msg.Error != nil {
		log.Printf("ERROR [explorer] delete: %v", msg.Error)
		return m, m.footer.Error(components.FailureEvent(jobs.KindDelete, msg.Target, msg.Transition().Detail))
	}
	m.footer.Clear()

	if msg.DeletedNode == nil {
		m.updateTableRows()
		return m, nil
	}

	// The row leaves the level it belongs to — its parent's, which is the
	// current one unless the user drilled elsewhere while the forge worked.
	// Removing it from whatever level was on screen instead would leave it in
	// the tree, and take the wrong row if an ID ever matched.
	deleted := msg.DeletedNode
	if deleted.Parent == nil {
		m.nodes = removeNode(m.nodes, deleted)
	} else {
		deleted.Parent.Children = removeNode(deleted.Parent.Children, deleted)
	}
	m.levelChanged(deleted.Parent)
	m.updateTableRows()
	gone := deleted.FullPath
// call, and the tree used to be emptied by a full refresh for the whole of it —
// the user saw a blank table and a silent footer, with nothing to say the thing
// they had just asked for was on its way. The row is the answer, and the
// registry is what keeps it honest (see jobs.go).
func (m Model) handleCreationSubmit(msg components.CreationFormSubmitMsg) (tea.Model, tea.Cmd) {
	m.mode = ModeNormal
	m.creationForm = nil

	if m.shared.Forge == nil {
		m.error = "Not connected to a forge"
		return m, nil
	}

	target := m.createTarget(msg)
	if m.busy(target) {
		return m, m.footer.Warn(busyMessage)
	}

	nodeType := NodeTypeProject
	work := m.createProject(msg, target)
	if msg.FormType == components.FormTypeGroup {
		nodeType = NodeTypeGroup
		work = m.createGroup(msg, target)
	}

	m.insertCreatingNode(msg, target, nodeType)
	return m, jobs.Start(createRun(target, msg.Name), work)
}

// createTarget is the path the row and the run are both keyed on, predicted
// from the parent being browsed and the slug the name becomes.
//
// A prediction, because the forge answers with the real one and is free to
// differ — but the row has to exist before there is an answer, so it needs a
// key that can be computed now. settleCreating is what reconciles the two.
func (m Model) createTarget(msg components.CreationFormSubmitMsg) string {
		}
	}
}

// createGroup creates a new namespace on the forge.
func (m Model) createGroup(msg components.CreationFormSubmitMsg, target string) tea.Cmd {
	backend := m.shared.Forge
	spec := forge.NewNamespace{
		Name:        msg.Name,
		Slug:        slugify(msg.Name),
		Description: msg.Description,
		Visibility:  msg.Visibility,
		ParentID:    msg.ParentID,
	}

	return func() tea.Msg {
		ctx, cancel := context.WithTimeout(context.Background(), forgeCallTimeout)
		defer cancel()
		ns, err := backend.CreateNamespace(ctx, spec)
		if err != nil {
			return GroupCreatedMsg{Target: target, Error: err}
		}
		return GroupCreatedMsg{Namespace: ns, Target: target}
	}
}

// What a forge call may take before the run gives up on it. A create is not
// cancellable by the user (jobs.Kind.Cancellable — a request already sent cannot
// be un-sent), so the bound is what keeps a stalled connection from holding the
// row, and the target, busy for the life of the session.
//
// The initial commit gets far longer than the rest: GitHub takes one request per
// file, and a template may hold template.MaxFiles of them.
const (
	forgeCallTimeout     = time.Minute
	initialCommitTimeout = 10 * time.Minute
)

// slugify turns a display name into the path segment a forge wants.
func slugify(name string) string {
	return strings.ToLower(strings.ReplaceAll(name, " ", "-"))
}

// createProject creates a new repository and, when a template was chosen, fills
// it with the template's files.
//
//
// No refresh: the forge has just told us what it made, so re-listing the whole
// tree to learn it would empty the table for the length of a second round trip.
// It is also what stops a create outliving a context switch from reloading the
// tree of the context it switched to.
//
// A failure goes to the footer rather than to m.error, which would replace the
// tree with an error screen — the one place the removed row cannot be seen.
func (m Model) handleGroupCreated(msg GroupCreatedMsg) (tea.Model, tea.Cmd) {
	if msg.Error != nil {
		log.Printf("ERROR [explorer] create namespace: %v", msg.Error)
		m.settleCreating(msg.Target, nil)
		return m, m.footer.Error(components.FailureEvent(jobs.KindCreate, msg.Target, msg.Transition().Detail))
	}

	node := nodeFromNamespace(msg.Namespace, nil)
	m.settleCreating(msg.Target, node)
	m.levelChanged(node.Parent)
	m.selectRow(node.FullPath)
	return m, indexCreated(node)
}

// handleProjectCreated resolves the placeholder row in place. See
// handleGroupCreated for why there is no refresh.
func (m Model) handleProjectCreated(msg ProjectCreatedMsg) (tea.Model, tea.Cmd) {
	if msg.Error != nil {
		log.Printf("ERROR [explorer] create repository: %v", msg.Error)
		m.settleCreating(msg.Target, nil)
		return m, m.footer.Error(components.FailureEvent(jobs.KindCreate, msg.Target, msg.Transition().Detail))
	}

	// The project exists whatever the template did, so the row settles either
	// way; only the message differs.
	node := nodeFromRepository(msg.Repository, nil)
	m.settleCreating(msg.Target, node)
	m.levelChanged(node.Parent)
	m.selectRow(node.FullPath)

	if msg.TemplateError != nil {
